// administrativeDirs is the closed list of derived-record directories. It is
// owned by the engine; adding a class is a contract change that needs an ADR.
var administrativeDirs = []string{".pose/indexes/", ".pose/results/", ".pose/state/", ".pose/assessments/"}

// materialIndexes are files inside an administrative directory that still
// change what the checks demand.
var materialIndexes = map[string]bool{".pose/indexes/validation-matrix.json": true}

// IsAdministrativePath reports whether p is a derived administrative record.
func IsAdministrativePath(p string) bool {
	if p == "" || p != path.Clean(p) || strings.HasPrefix(p, "/") || strings.HasPrefix(p, "../") {
		return false
	}
	if materialIndexes[p] {
		return false
	}
	if !recordExtensions[strings.ToLower(path.Ext(p))] {
		return false
	}
	for _, dir := range administrativeDirs {
		if strings.HasPrefix(p, dir) {
			return true
		}
	}
	if rest, ok := strings.CutPrefix(p, ".pose/"); ok {
		if i := strings.Index(rest, "/"); i > 0 && strings.HasPrefix(rest[:i], "review-") {
			return true
		}
	}
	return false
}

// recordExtensions are the data formats a derived record is written in. Code or
// a script stored in a class is material: that keeps a source file moved or
// copied into a class from hiding its later edits. A copied data file stays
// indistinguishable from a record; a check that reads data out of a derived-record
// directory is outside this contract (ADR validation-evidence-binds-to-validated-material).
var recordExtensions = map[string]bool{".json": true, ".jsonl": true, ".ndjson": true, ".md": true, ".txt": true, ".log": true, ".transcript": true}

// TreeEntry is one entry of the validated head's tree.
type TreeEntry struct{ Mode, Blob string }

func regularMode(mode string) bool { return mode == "100644" || mode == "100755" }

// MaterialInputs are what a material digest is computed from: the paths a change
// set names (both sides of a rename, and the validation matrix) and the
// destinations of renames. They are stored with the set so the digest can be
// recomputed against the current tree without the commits' own records.
type MaterialInputs struct {
	Names []string `json:"names"`
	Moved []string `json:"moved,omitempty"`
}

// MaterialInputsOf derives the inputs from per-commit path records. They must
// be unmerged: folding a create and a later rename into one creation would hide
// that the file moved into a class.
func MaterialInputsOf(paths []ObservedPath) MaterialInputs {
	names := map[string]bool{".pose/indexes/validation-matrix.json": true}
	moved := map[string]bool{}
	for _, p := range paths {
		for _, name := range []string{p.Path, p.OldPath, p.NewPath} {
			if name != "" {
				names[name] = true
			}
		}
		// A rename destination is material whatever directory it lands in:
		// otherwise moving a source file into a class would hide its later edits.
		if p.OldPath != "" && p.NewPath != "" {
			moved[p.NewPath] = true
		}
	}
	in := MaterialInputs{}
	for name := range names {
		in.Names = append(in.Names, name)
	}
	for name := range moved {
		in.Moved = append(in.Moved, name)
	}
	sort.Strings(in.Names)
	sort.Strings(in.Moved)
	return in
}

